		{
			return Detail::EvaluateTensorComponentPartial<Detail::FirstDerivativeOrder::One>(
				[&](const auto& x) { return f.Component(i, j, k, l, x); }, deriv_index, point, h, error);
		}

		/********************************************************************************************************************/
		/********                               Numerical derivatives of SECOND order                                ********/
		/********************************************************************************************************************/
