///////////////////////////   mml/tools/serializer/SerializerFunctions.h   ///////////////////////////
namespace MML
{
	namespace Serializer
	{
		//===================================================================================
		// Real function serialization
		//===================================================================================

		/// @brief Serialize a real function to a stream at equally-spaced points
		/// @details Core stream version - writes to any std::ostream (stringstream, cout, etc.)
		/// @param out Output stream to write to
		/// @param f The real function to serialize
		/// @param title Display title for the data
		/// @param x1 Start of parameter range
		/// @param x2 End of parameter range
		/// @param numPoints Number of evaluation points (must be >= 2)
		/// @param precision Decimal places for output (default: 15)
		/// @return SerializeResult with success flag and error details
		inline SerializeResult SaveRealFunc(std::ostream& out, const IRealFunction& f, std::string title,
											Real x1, Real x2, int numPoints, int precision = 15)
		{
			if (numPoints < 2)
				return {false, SerializeError::INVALID_PARAMETERS, "numPoints must be >= 2"};
			if (x1 >= x2)
				return {false, SerializeError::INVALID_PARAMETERS, "x1 must be less than x2"};

			try
			{
				out.precision(precision);
				WriteRealFuncHeader(out, SerializeFormatType::REAL_FUNCTION, title, x1, x2, numPoints);

				Real step = (x2 - x1) / (numPoints - 1);
				for (int i = 0; i < numPoints; i++)
				{
					Real x = x1 + i * step;
					out << x << " " << f(x) << std::endl;
				}
				return {true, SerializeError::OK, "Success"};
			}
			catch (const std::exception& e)
			{
				return {false, SerializeError::WRITE_FAILED, std::string("Write error: ") + e.what()};
			}
		}

		/// @brief Serialize a real function to file at equally-spaced points (file version)
		/// @details Convenience wrapper that opens file and delegates to stream version
		inline SerializeResult SaveRealFunc(const IRealFunction& f, std::string title,
											Real x1, Real x2, int numPoints, std::string fileName, int precision = 15)
		{
			if (fileName.empty())
				return {false, SerializeError::INVALID_PARAMETERS, "fileName cannot be empty"};

			std::ofstream file(fileName);
			if (!file.is_open())
				return {false, SerializeError::FILE_NOT_OPENED, "Cannot open file: " + fileName};

			auto result = SaveRealFunc(file, f, title, x1, x2, numPoints, precision);
			file.close();
			return result;
		}

		/// @brief Serialize a real function to a stream at specified points
		/// @details Core stream version - writes to any std::ostream (stringstream, cout, etc.)
		inline SerializeResult SaveRealFunc(std::ostream& out, const IRealFunction& f, std::string title,
											Vector<Real> points, int precision = 15)
		{
			if (points.size() < 2)
				return {false, SerializeError::INVALID_PARAMETERS, "points vector must have at least 2 elements"};

			try
			{
				out.precision(precision);
				WriteRealFuncHeader(out, SerializeFormatType::REAL_FUNCTION, title, points[0], points[points.size() - 1], static_cast<int>(points.size()));

				for (int i = 0; i < points.size(); i++)
				{
					Real x = points[i];
					out << x << " " << f(x) << std::endl;
				}
				return {true, SerializeError::OK, "Success"};
			}
			catch (const std::exception& e)
			{
				return {false, SerializeError::WRITE_FAILED, std::string("Write error: ") + e.what()};
			}
		}

		/// @brief Serialize a real function to file at specified points (file version)
		inline SerializeResult SaveRealFunc(const IRealFunction& f, std::string title,
											Vector<Real> points, std::string fileName, int precision = 15)
		{
			if (fileName.empty())
				return {false, SerializeError::INVALID_PARAMETERS, "fileName cannot be empty"};

			std::ofstream file(fileName);
			if (!file.is_open())
				return {false, SerializeError::FILE_NOT_OPENED, "Cannot open file: " + fileName};

			auto result = SaveRealFunc(file, f, title, points, precision);
			file.close();
			return result;
		}

		/// @brief Serialize a real function to stream saving only function values (space-optimized)
		inline SerializeResult SaveRealFuncEquallySpaced(std::ostream& out, const IRealFunction& f, std::string title,
														 Real x1, Real x2, int numPoints, int precision = 15)
		{
			if (numPoints < 2)
				return {false, SerializeError::INVALID_PARAMETERS, "numPoints must be >= 2"};
			if (x1 >= x2)
				return {false, SerializeError::INVALID_PARAMETERS, "x1 must be less than x2"};

			try
			{
				out.precision(precision);
				WriteRealFuncHeader(out, SerializeFormatType::REAL_FUNCTION_EQUALLY_SPACED, title, x1, x2, numPoints);

				Real step = (x2 - x1) / (numPoints - 1);
				for (int i = 0; i < numPoints; i++)
				{
					Real x = x1 + i * step;
					out << f(x) << std::endl;
				}
				return {true, SerializeError::OK, "Success"};
			}
			catch (const std::exception& e)
			{
				return {false, SerializeError::WRITE_FAILED, std::string("Write error: ") + e.what()};
			}
		}

		/// @brief Serialize a real function saving only function values to file (space-optimized)
		inline SerializeResult SaveRealFuncEquallySpaced(const IRealFunction& f, std::string title,
														 Real x1, Real x2, int numPoints, std::string fileName, int precision = 15)
		{
			if (fileName.empty())
				return {false, SerializeError::INVALID_PARAMETERS, "fileName cannot be empty"};

			std::ofstream file(fileName);
			if (!file.is_open())
				return {false, SerializeError::FILE_NOT_OPENED, "Cannot open file: " + fileName};

			auto result = SaveRealFuncEquallySpaced(file, f, title, x1, x2, numPoints, precision);
			file.close();
			return result;
		}

		//===================================================================================
		// Multi-function serialization
		//===================================================================================

		/// @brief Serialize multiple real functions to a stream
		inline SerializeResult SaveRealMultiFunc(std::ostream& out, const std::vector<IRealFunction*> &funcs, std::string title,
												 std::vector<std::string> legend,
												 Real x1, Real x2, int numPoints, int precision = 15)
		{
			if (funcs.empty())
				return {false, SerializeError::INVALID_PARAMETERS, "funcs vector cannot be empty"};
			if (numPoints < 2)
				return {false, SerializeError::INVALID_PARAMETERS, "numPoints must be >= 2"};
			if (x1 >= x2)
				return {false, SerializeError::INVALID_PARAMETERS, "x1 must be less than x2"};
			if (funcs.size() != legend.size())
				return {false, SerializeError::INVALID_PARAMETERS, "funcs and legend sizes must match"};

			try
			{
				out.precision(precision);
				WriteRealMultiFuncHeader(out, title, funcs.size(), legend, x1, x2, numPoints);

				for (int i = 0; i < numPoints; i++)
				{
					Real x = x1 + (x2 - x1) * i / (numPoints - 1);
					out << x << " ";

					for (size_t j = 0; j < funcs.size(); j++)
						out << (*(funcs[j]))(x) << " ";

					out << std::endl;
				}
				return {true, SerializeError::OK, "Success"};
			}
			catch (const std::exception& e)
			{
				return {false, SerializeError::WRITE_FAILED, std::string("Write error: ") + e.what()};
			}
		}

		/// @brief Serialize multiple real functions to a single file
		inline SerializeResult SaveRealMultiFunc(const std::vector<IRealFunction*> &funcs, std::string title,
												 std::vector<std::string> legend,
												 Real x1, Real x2, int numPoints, std::string fileName, int precision = 15)
		{
			if (fileName.empty())
				return {false, SerializeError::INVALID_PARAMETERS, "fileName cannot be empty"};

			std::ofstream file(fileName);
			if (!file.is_open())
				return {false, SerializeError::FILE_NOT_OPENED, "Cannot open file: " + fileName};

			auto result = SaveRealMultiFunc(file, funcs, title, legend, x1, x2, numPoints, precision);
			file.close();
			return result;
		}

		/// @brief Serialize multiple interpolation functions to file
		template<class InterpFunc>
		SerializeResult SaveRealMultiFunc(const std::vector<InterpFunc>& funcs, std::string title,
									 std::vector<std::string> legend,
									 Real x1, Real x2, int numPoints, std::string fileName)
		{
			if (funcs.empty())
				return {false, SerializeError::INVALID_PARAMETERS, "funcs vector cannot be empty"};
			if (numPoints < 2)
				return {false, SerializeError::INVALID_PARAMETERS, "numPoints must be >= 2"};
			if (x1 >= x2)
				return {false, SerializeError::INVALID_PARAMETERS, "x1 must be less than x2"};
			if (funcs.size() != legend.size())
				return {false, SerializeError::INVALID_PARAMETERS, "funcs and legend sizes must match"};
			if (fileName.empty())
				return {false, SerializeError::INVALID_PARAMETERS, "fileName cannot be empty"};

			std::ofstream file(fileName);
			if (!file.is_open())
				return {false, SerializeError::FILE_NOT_OPENED, "Cannot open file: " + fileName};

			try
			{
				WriteRealMultiFuncHeader(file, title, funcs.size(), legend, x1, x2, numPoints);

				for (int i = 0; i < numPoints; i++)
				{
					Real x = x1 + (x2 - x1) * i / (numPoints - 1);
					file << x << " ";

					for (int j = 0; j < funcs.size(); j++)
						file << funcs[j](x) << " ";

					file << std::endl;
				}
				file.close();
				return {true, SerializeError::OK, "Success"};
			}
			catch (const std::exception& e)
			{
				return {false, SerializeError::WRITE_FAILED, std::string("Write error: ") + e.what()};
			}
		}

	} // namespace Serializer
} // namespace MML

///////////////////////////   mml/tools/serializer/SerializerCurves.h   ///////////////////////////
namespace MML
{
	namespace Serializer
	{
		//===================================================================================
		// Parametric curve serialization
		//===================================================================================

		/// @brief Serialize a parametric curve to file at equally-spaced parameter values
		/// @return SerializeResult with success flag and error details
		template<int N>
		inline SerializeResult SaveParamCurve(const IRealToVectorFunction<N>& f, std::string inType, std::string title,
		                                      Real t1, Real t2, int numPoints, std::string fileName)
		{
			if (fileName.empty())
				return {false, SerializeError::INVALID_PARAMETERS, "fileName cannot be empty"};
			if (numPoints < 2)
				return {false, SerializeError::INVALID_PARAMETERS, "numPoints must be >= 2"};
			if (t1 >= t2)
				return {false, SerializeError::INVALID_PARAMETERS, "t1 must be < t2"};

			std::ofstream file(fileName);
			if (!file.is_open())
				return {false, SerializeError::FILE_NOT_OPENED, "Cannot open file: " + fileName};

			try
			{
				auto headerResult = WriteParamCurveHeader(file, inType, title, t1, t2, numPoints);
				if (!headerResult.success)
					return headerResult;

				Real delta = (t2 - t1) / (numPoints - 1);
				for (int n = 0; n < numPoints; n++)
				{
					Real t = t1 + n * delta;
					file << t << " ";
					auto val = f(t);
					for (int i = 0; i < N; i++)
						file << val[i] << " ";
					file << std::endl;
				}
				file.close();
				return {true, SerializeError::OK, "Successfully saved parametric curve"};
			}
			catch (const std::exception& e)
			{
				file.close();
				return {false, SerializeError::WRITE_FAILED, std::string("Write error: ") + e.what()};
			}
		}

		/// @brief Serialize a parametric curve to file at specified parameter values
		/// @return SerializeResult with success flag and error details
		template<int N>
		inline SerializeResult SaveParamCurve(const IRealToVectorFunction<N>& f, std::string inType, std::string title,
		                                      Vector<Real> points, std::string fileName)
		{
			if (fileName.empty())
				return {false, SerializeError::INVALID_PARAMETERS, "fileName cannot be empty"};
			if (points.size() < 2)
				return {false, SerializeError::INVALID_PARAMETERS, "points vector must have at least 2 elements"};

			std::ofstream file(fileName);
			if (!file.is_open())
				return {false, SerializeError::FILE_NOT_OPENED, "Cannot open file: " + fileName};

			try
			{
				auto headerResult = WriteParamCurveHeader(file, inType, title, points[0], points[points.size() - 1], static_cast<int>(points.size()));
				if (!headerResult.success)
					return headerResult;

				for (int i = 0; i < points.size(); i++)
				{
					Real t = points[i];
					file << t << " ";
					auto val = f(t);
					for (int j = 0; j < N; j++)
						file << val[j] << " ";
					file << std::endl;
				}

				file.close();
				return {true, SerializeError::OK, "Successfully saved parametric curve"};
			}
			catch (const std::exception& e)
			{
				file.close();
				return {false, SerializeError::WRITE_FAILED, std::string("Write error: ") + e.what()};
			}
		}

		/// @brief Serialize pre-computed curve points to file at equally-spaced parameter values
		/// @return SerializeResult with success flag and error details
		template<int N>
		inline SerializeResult SaveAsParamCurve(std::vector<VectorN<Real, N>> vals, std::string inType, std::string title,
		                                        Real t1, Real t2, int numPoints, std::string fileName)
		{
			if (fileName.empty())
				return {false, SerializeError::INVALID_PARAMETERS, "fileName cannot be empty"};
			if (numPoints < 2)
				return {false, SerializeError::INVALID_PARAMETERS, "numPoints must be >= 2"};
			if (t1 >= t2)
				return {false, SerializeError::INVALID_PARAMETERS, "t1 must be < t2"};
			if (static_cast<int>(vals.size()) < numPoints)
				return {false, SerializeError::INVALID_PARAMETERS, "vals vector size must be >= numPoints"};

			std::ofstream file(fileName);
			if (!file.is_open())
				return {false, SerializeError::FILE_NOT_OPENED, "Cannot open file: " + fileName};

			try
			{
				auto headerResult = WriteParamCurveHeader(file, inType, title, t1, t2, numPoints);
				if (!headerResult.success)
					return headerResult;

				Real delta = (t2 - t1) / (numPoints - 1);
				for (int i = 0; i < numPoints; i++)
				{
					Real t = t1 + i * delta;
					file << t << " ";
					for (int j = 0; j < N; j++)
						file << vals[i][j] << " ";
					file << std::endl;
				}
				file.close();
				return {true, SerializeError::OK, "Successfully saved parametric curve"};
			}
			catch (const std::exception& e)
			{
				file.close();
				return {false, SerializeError::WRITE_FAILED, std::string("Write error: ") + e.what()};
			}
		}

		/// @brief Serialize pre-computed curve points to file at specified parameter values
		/// @return SerializeResult with success flag and error details
		template<int N>
		inline SerializeResult SaveAsParamCurve(std::vector<VectorN<Real, N>> vals, std::string inType, std::string title,
		                                        Vector<Real> points, std::string fileName)
		{
			if (fileName.empty())
				return {false, SerializeError::INVALID_PARAMETERS, "fileName cannot be empty"};
			if (points.size() < 2)
				return {false, SerializeError::INVALID_PARAMETERS, "points vector must have at least 2 elements"};
			if (vals.size() < points.size())
				return {false, SerializeError::INVALID_PARAMETERS, "vals vector size must be >= points size"};

			std::ofstream file(fileName);
			if (!file.is_open())
				return {false, SerializeError::FILE_NOT_OPENED, "Cannot open file: " + fileName};

			try
			{
				auto headerResult = WriteParamCurveHeader(file, inType, title, points[0], points[points.size() - 1], static_cast<int>(points.size()));
				if (!headerResult.success)
					return headerResult;

				for (int i = 0; i < points.size(); i++)
				{
					Real t = points[i];
					file << t << " ";
					for (int j = 0; j < N; j++)
						file << vals[i][j] << " ";
					file << std::endl;
				}
				file.close();
				return {true, SerializeError::OK, "Successfully saved parametric curve"};
			}
			catch (const std::exception& e)
			{
				file.close();
				return {false, SerializeError::WRITE_FAILED, std::string("Write error: ") + e.what()};
			}
		}

		/// @brief Serialize a parametric 2D curve from component vectors
		/// @details Saves a 2D parametric curve (x(t), y(t)) from explicit vector pairs to file.
		/// Useful for plotting trajectories and curves defined by separate x and y vectors.
		/// Format: [t, x(t), y(t)] triplets, one per line.
		/// @param vec_x Vector of x-coordinates (must be same size as vec_y)
		/// @param vec_y Vector of y-coordinates (must be same size as vec_x)
		/// @param fileName Output file path for the parametric curve
		/// @param t1 Start of parameter range (default: 0.0, used to label parameter axis)
		/// @param t2 End of parameter range (default: 1.0, used to label parameter axis)
		/// @return SerializeResult with success flag and error details
		/// @pre vec_x.size() >= 2, vec_x.size() == vec_y.size(), t1 < t2, !fileName.empty()
		/// @post File is closed and flushed; parameter range [t1, t2] mapped across vector indices
		/// @note Parameter values are computed linearly from t1 to t2 across indices
		inline SerializeResult SaveAsParamCurve2D(const Vector<Real>& vec_x, const Vector<Real>& vec_y,
		                                          std::string title, std::string fileName, Real t1 = 0.0, Real t2 = 1.0)
		{
			// Validate parameters
			if (fileName.empty()) {
				return { false, SerializeError::INVALID_PARAMETERS, "fileName cannot be empty" };
			}
			if (vec_x.size() < 2) {
				return { false, SerializeError::INVALID_PARAMETERS, "vec_x must have at least 2 elements" };
			}
			if (vec_x.size() != vec_y.size()) {
				return { false, SerializeError::INVALID_PARAMETERS, "vec_x and vec_y must have same size" };
			}
			if (t1 >= t2) {
				return { false, SerializeError::INVALID_PARAMETERS, "t1 must be < t2" };
			}

			std::ofstream file(fileName);
			if (!file.is_open()) {
				return { false, SerializeError::FILE_NOT_OPENED, "Cannot open file: " + fileName };
			}

			try {
				WriteParamCurveHeader(file, SerializeFormatType::PARAMETRIC_CURVE_CARTESIAN_2D, title, t1, t2, static_cast<int>(vec_x.size()));

				for (int i = 0; i < vec_x.size(); i++)
				{
					Real t = t1 + (t2 - t1) * i / (vec_x.size() - 1);
					file << t << " " << vec_x[i] << " " << vec_y[i] << std::endl;
				}
				file.close();
				return { true, SerializeError::OK, "Successfully saved parametric curve 2D" };
			}
			catch (const std::exception& e) {
				file.close();
				return { false, SerializeError::WRITE_FAILED, std::string("Write error: ") + e.what() };
			}
		}

		//===================================================================================
		// Helper/forwarding functions - SerializeResult versions
		//===================================================================================

		/// @brief Serialize a 2D Cartesian parametric curve to file
		/// @return SerializeResult with success flag and error details
		inline SerializeResult SaveParamCurveCartesian2DResult(const IRealToVectorFunction<2>& f, std::string title,
		                                                       Real t1, Real t2, int numPoints, std::string fileName)
		{
			return SaveParamCurve<2>(f, SerializeFormatType::PARAMETRIC_CURVE_CARTESIAN_2D, title, t1, t2, numPoints, fileName);
		}

		/// @brief Serialize a 3D Cartesian parametric curve to file
		/// @return SerializeResult with success flag and error details
		inline SerializeResult SaveParamCurveCartesian3DResult(const IRealToVectorFunction<3>& f, std::string title,
		                                                       Real t1, Real t2, int numPoints, std::string fileName)
		{
			return SaveParamCurve<3>(f, SerializeFormatType::PARAMETRIC_CURVE_CARTESIAN_3D, title, t1, t2, numPoints, fileName);
		}

	} // namespace Serializer
} // namespace MML

///////////////////////////   mml/tools/serializer/SerializerSurfaces.h   ///////////////////////////
namespace MML
{
	namespace Serializer
	{
		//===================================================================================
		// Parametric Surface Serialization
		//===================================================================================

		/// @brief Serialize a 3D parametric surface to file
		/// @details Saves a parametric surface r(u,w) = (x(u,w), y(u,w), z(u,w)) evaluated on a
		/// rectangular parameter grid to file. Each point contains parameter values and 3D position.
		/// Format: Header with grid parameters, then rows of [u, w, x, y, z].
		/// Ideal for 3D surface visualization of spheres, tori, and other parametric shapes.
		/// @param surface The parametric surface function (R² → R³)
		/// @param title Display title for the surface
		/// @param u1 Start of u parameter range
		/// @param u2 End of u parameter range
		/// @param numPointsU Number of grid points along u (must be >= 2)
		/// @param w1 Start of w parameter range
		/// @param w2 End of w parameter range
		/// @param numPointsW Number of grid points along w (must be >= 2)
		/// @param fileName Output file path
		/// @return SerializeResult with success flag and error details
		inline SerializeResult SaveParametricSurface(const IParametricSurface<3>& surface, std::string title,
		                                             Real u1, Real u2, int numPointsU,
		                                             Real w1, Real w2, int numPointsW,
		                                             std::string fileName)
		{
			// Validate parameters
			if (numPointsU < 2 || numPointsW < 2)
				return {false, SerializeError::INVALID_PARAMETERS, "numPointsU and numPointsW must be >= 2"};
			if (u1 >= u2 || w1 >= w2)
				return {false, SerializeError::INVALID_PARAMETERS, "u1 < u2 and w1 < w2 required"};
			if (fileName.empty())
				return {false, SerializeError::INVALID_PARAMETERS, "fileName cannot be empty"};

			std::ofstream file(fileName);
			if (!file.is_open())
				return {false, SerializeError::FILE_NOT_OPENED, "Cannot open file: " + fileName};

			try
			{
				auto headerResult = WriteParametricSurfaceHeader(file, title, u1, u2, numPointsU, w1, w2, numPointsW);
				if (!headerResult.success)
					return headerResult;

				// Write grid data
				Real stepU = (u2 - u1) / (numPointsU - 1);
				Real stepW = (w2 - w1) / (numPointsW - 1);

				for (int i = 0; i < numPointsU; i++)
				{
					Real u = u1 + i * stepU;
					for (int j = 0; j < numPointsW; j++)
					{
						Real w = w1 + j * stepW;
						VectorN<Real, 3> pos = surface(u, w);
						file << u << " " << w << " " << pos[0] << " " << pos[1] << " " << pos[2] << std::endl;
					}
				}

				file.close();
				return {true, SerializeError::OK, "Success"};
			}
			catch (const std::exception& e)
			{
				return {false, SerializeError::WRITE_FAILED, std::string("Write error: ") + e.what()};
			}
		}

		/// @brief Serialize a general R² → R³ function as a parametric surface
		/// @details Lower-level function that works with any IVectorFunctionNM<2,3>.
		/// Useful when you have a lambda or custom function that isn't wrapped in IParametricSurface.
		inline SerializeResult SaveParametricSurface(const IVectorFunctionNM<2, 3>& f, std::string title,
		                                             Real u1, Real u2, int numPointsU,
		                                             Real w1, Real w2, int numPointsW,
		                                             std::string fileName)
		{
			// Validate parameters
			if (numPointsU < 2 || numPointsW < 2)
				return {false, SerializeError::INVALID_PARAMETERS, "numPointsU and numPointsW must be >= 2"};
			if (u1 >= u2 || w1 >= w2)
				return {false, SerializeError::INVALID_PARAMETERS, "u1 < u2 and w1 < w2 required"};
			if (fileName.empty())
				return {false, SerializeError::INVALID_PARAMETERS, "fileName cannot be empty"};

			std::ofstream file(fileName);
			if (!file.is_open())
				return {false, SerializeError::FILE_NOT_OPENED, "Cannot open file: " + fileName};

			try
			{
				auto headerResult = WriteParametricSurfaceHeader(file, title, u1, u2, numPointsU, w1, w2, numPointsW);
				if (!headerResult.success)
					return headerResult;

				// Write grid data
				Real stepU = (u2 - u1) / (numPointsU - 1);
				Real stepW = (w2 - w1) / (numPointsW - 1);

				for (int i = 0; i < numPointsU; i++)
				{
					Real u = u1 + i * stepU;
					for (int j = 0; j < numPointsW; j++)
					{
						Real w = w1 + j * stepW;
						VectorN<Real, 3> pos = f(VectorN<Real, 2>{u, w});
						file << u << " " << w << " " << pos[0] << " " << pos[1] << " " << pos[2] << std::endl;
					}
				}

				file.close();
				return {true, SerializeError::OK, "Success"};
			}
			catch (const std::exception& e)
			{
				return {false, SerializeError::WRITE_FAILED, std::string("Write error: ") + e.what()};
			}
		}

		/// @brief Serialize a 3D parametric surface using its intrinsic bounds
		/// @details Convenience overload that uses the surface's getMinU/MaxU/MinW/MaxW methods
		/// to determine the parameter range automatically.
		inline SerializeResult SaveParametricSurface(const IParametricSurfaceRect<3>& surface, std::string title,
		                                             int numPointsU, int numPointsW,
		                                             std::string fileName)
		{
			return SaveParametricSurface(
				static_cast<const IVectorFunctionNM<2, 3>&>(surface), title,
				surface.getMinU(), surface.getMaxU(), numPointsU,
				surface.getMinW(), surface.getMaxW(), numPointsW,
				fileName);
		}

		//===================================================================================
		// Scalar function serialization
		//===================================================================================

		/// @brief Serialize a 2D scalar function (z=f(x,y)) to a grid file
		/// @details Saves a 2D scalar function evaluated on a rectangular grid to file.
		/// Format: Header with grid parameters, then value rows (one per y-line, varying x).
		/// Ideal for surface plots and heatmaps.
		inline SerializeResult SaveScalarFunc2DCartesian(const IScalarFunction<2>& f, std::string title,
		                                                 Real x1, Real x2, int numPointsX,
		                                                 Real y1, Real y2, int numPointsY, std::string fileName)
		{
			// Validate parameters
			if (numPointsX < 2 || numPointsY < 2)
				return {false, SerializeError::INVALID_PARAMETERS, "numPointsX and numPointsY must be >= 2"};
			if (x1 >= x2 || y1 >= y2)
				return {false, SerializeError::INVALID_PARAMETERS, "x1 < x2 and y1 < y2 required"};
			if (fileName.empty())
				return {false, SerializeError::INVALID_PARAMETERS, "fileName cannot be empty"};

			std::ofstream file(fileName);
			if (!file.is_open())
				return {false, SerializeError::FILE_NOT_OPENED, "Cannot open file: " + fileName};

			try
			{
				auto headerResult = WriteScalarFunc2DHeader(file, title, x1, x2, numPointsX, y1, y2, numPointsY);
				if (!headerResult.success)
					return headerResult;

				Real stepX = (x2 - x1) / (numPointsX - 1);
				Real stepY = (y2 - y1) / (numPointsY - 1);
				for (int i = 0; i < numPointsX; i++)
				{
					for (int j = 0; j < numPointsY; j++)
					{
						Real x = x1 + i * stepX;
						Real y = y1 + j * stepY;
						file << x << " " << y << " " << f(VectorN<Real, 2>{x, y}) << std::endl;
					}
				}
				file.close();
				return {true, SerializeError::OK, "Success"};
			}
			catch (const std::exception& e)
			{
				return {false, SerializeError::WRITE_FAILED, std::string("Write error: ") + e.what()};
			}
		}

		/// @brief Serialize a 3D scalar function (w=f(x,y,z)) to a grid file
		/// @details Saves a 3D scalar function evaluated on a rectangular 3D grid to file.
		/// Format: Header with grid parameters, then value rows (one per point in 3D grid).
		/// Useful for volumetric data and 3D scalar field visualization.
		inline SerializeResult SaveScalarFunc3DCartesian(const IScalarFunction<3>& f, std::string title,
		                                                 Real x1, Real x2, int numPointsX,
		                                                 Real y1, Real y2, int numPointsY,
		                                                 Real z1, Real z2, int numPointsZ, std::string fileName)
		{
			// Validate parameters
			if (numPointsX < 2 || numPointsY < 2 || numPointsZ < 2)
				return {false, SerializeError::INVALID_PARAMETERS, "numPointsX, numPointsY, and numPointsZ must be >= 2"};
			if (x1 >= x2 || y1 >= y2 || z1 >= z2)
				return {false, SerializeError::INVALID_PARAMETERS, "x1 < x2, y1 < y2, and z1 < z2 required"};
			if (fileName.empty())
				return {false, SerializeError::INVALID_PARAMETERS, "fileName cannot be empty"};

			std::ofstream file(fileName);
			if (!file.is_open())
				return {false, SerializeError::FILE_NOT_OPENED, "Cannot open file: " + fileName};

			try
			{
				auto headerResult = WriteScalarFunc3DHeader(file, title, x1, x2, numPointsX, y1, y2, numPointsY, z1, z2, numPointsZ);
				if (!headerResult.success)
					return headerResult;

				Real stepX = (x2 - x1) / (numPointsX - 1);
				Real stepY = (y2 - y1) / (numPointsY - 1);
				Real stepZ = (z2 - z1) / (numPointsZ - 1);
				for (int i = 0; i < numPointsX; i++)
				{
					for (int j = 0; j < numPointsY; j++)
					{
						for (int k = 0; k < numPointsZ; k++)
						{
							Real x = x1 + i * stepX;
							Real y = y1 + j * stepY;
							Real z = z1 + k * stepZ;
							file << x << " " << y << " " << z << " " << f(VectorN<Real, 3>{x, y, z}) << std::endl;
						}
					}
				}
				file.close();
				return {true, SerializeError::OK, "Success"};
			}
			catch (const std::exception& e)
			{
				return {false, SerializeError::WRITE_FAILED, std::string("Write error: ") + e.what()};
			}
		}

		//===================================================================================
		// Grid function serialization
		//===================================================================================

		/// @brief Serialize a 2D grid function (e.g., PDE solution) directly to surface visualization format
		/// @details Saves grid data without the overhead of wrapping in IScalarFunction<2>.
		/// Output format is identical to SaveScalarFunc2DCartesian, allowing direct
		/// visualization with the surface visualizer.
		///
		/// @tparam GridFunc Type with grid() method returning a grid with domain(), numNodesX/Y(), x(i), y(j)
		/// and operator()(i,j) for value access
		/// @param gridFunc The grid function to serialize (e.g., MML::PDE::GridFunction2D)
		/// @param title Display title for the surface plot
		/// @param fileName Output file path
		/// @param scaleXY Scale factor for x,y coordinates (default 1.0)
		/// @param scaleValue Scale factor for values (default 1.0)
		/// @return SerializeResult with success flag and error details
		template<typename GridFunc>
		inline SerializeResult SaveGridFunction2D(const GridFunc& gridFunc, std::string title,
		                                          std::string fileName,
		                                          Real scaleXY = 1.0, Real scaleValue = 1.0)
		{
			if (fileName.empty())
				return {false, SerializeError::INVALID_PARAMETERS, "fileName cannot be empty"};

			std::ofstream file(fileName);
			if (!file.is_open())
				return {false, SerializeError::FILE_NOT_OPENED, "Cannot open file: " + fileName};

			try
			{
				const auto& grid = gridFunc.grid();
				const auto& domain = grid.domain();

				int numPointsX = grid.numNodesX();
				int numPointsY = grid.numNodesY();

				// Apply scaling to domain bounds
				Real x1 = domain.xMin() * scaleXY;
				Real x2 = domain.xMax() * scaleXY;
				Real y1 = domain.yMin() * scaleXY;
				Real y2 = domain.yMax() * scaleXY;

				auto headerResult = WriteScalarFunc2DHeader(file, title, x1, x2, numPointsX, y1, y2, numPointsY);
				if (!headerResult.success)
					return headerResult;

				// Output grid values directly (no interpolation needed)
				for (int i = 0; i < numPointsX; i++)
				{
					for (int j = 0; j < numPointsY; j++)
					{
						Real x = grid.x(i) * scaleXY;
						Real y = grid.y(j) * scaleXY;
						Real value = gridFunc(i, j) * scaleValue;
						file << x << " " << y << " " << value << std::endl;
					}
				}
				file.close();
				return {true, SerializeError::OK, "Success"};
			}
			catch (const std::exception& e)
			{
				return {false, SerializeError::WRITE_FAILED, std::string("Write error: ") + e.what()};
			}
		}

	} // namespace Serializer
} // namespace MML

